SELECT

FROM RwaInstSpvProductDividendSnapshot a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.instSpvProductDividendNo = #{instSpvProductDividendNo}


    AND a.walletAddress = #{walletAddress}


    AND a.holdAmount = #{holdAmount}


    AND a.dividendAmount = #{dividendAmount}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM RwaInstSpvProductDividendSnapshot a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.instInvestorId = #{instInvestorId}


    AND a.instSpvProductId = #{instSpvProductId}


    AND a.instSpvProductDividendNo LIKE CONCAT('%',#{instSpvProductDividendNo}, '%')


    AND a.walletAddress LIKE CONCAT('%',#{walletAddress}, '%')


    AND a.holdAmount = #{holdAmount}


    AND a.dividendAmount = #{dividendAmount}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
